/**
 * Unit tests for BeanDeserializerBase#deserializeFromObjectId.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class BeanDeserializerBase_deserializeFromObjectId_TriageGen1Test {

    private TestBeanDeserializer deserializer;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private ObjectIdReader mockObjectIdReader;
    private ReadableObjectId mockReadableObjectId;
    private JsonGenerator mockGenerator;

    // Test subclass to access protected method and inject dependencies
    private static class TestBeanDeserializer extends BeanDeserializerBase {
        private final Class<?> _beanType = Object.class;

        protected TestBeanDeserializer(ObjectIdReader oir) {
            super(null, oir);
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) {
            return null;
        }

        @Override
        public abstract JsonDeserializer<Object> deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException;

        @Override
        public abstract Object deserializeWithType(JsonParser p, DeserializationContext ctxt, com.fasterxml.jackson.databind.deser.TypeDeserializer typeDeserializer) throws IOException;

        @Override
        protected BeanDeserializerBase asArrayDeserializer() {
            return null;
        }

        // Expose the protected method for testing
        @Override
        public Object exposeDeserializeFromObjectId(JsonParser p, DeserializationContext ctxt) throws IOException {
            return super.deserializeFromObjectId(p, ctxt);
        }

        // Mocking internal field _beanType via reflection or subclassing logic is hard in Jackson, 
        // but the method uses _beanType which is a field in the base class. 
        // In actual Jackson, this is a field. We assume the test environment allows access or we mock the behavior.
    }

    // Mocking JsonGenerator since it's required by ObjectIdReader
    interface JsonGenerator extends com.fasterxml.jackson.core.JsonGenerator {}

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockObjectIdReader = mock(ObjectIdReader.class);
        mockReadableObjectId = mock(ReadableObjectId.class);
        mockGenerator = mock(JsonGenerator.class);

        // Setup the reader to return the mockable object
        when(mockObjectIdReader.getGenerator()).thenReturn(mockGenerator);

        deserializer = new TestBeanDeserializer(mockObjectIdReader) {
            @Override
            public JsonDeserializer<Object> deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException {
                return null;
            }
            @Override
            public Object deserializeWithType(JsonParser p, DeserializationContext ctxt, com.fasterxml.jackson.databind.deser.TypeDeserializer typeDeserializer) throws IOException {
                return null;
            }
            @Override
            protected BeanDeserializerBase asArrayDeserializer() {
                return null;
            }
        };
    }

    @Test
    public void testDeserializeFromObjectId_Success() throws IOException {
        // Arrange
        Object expectedPojo = new Object();
        Object id = "id-123";

        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(id);
        when(mockContext.findObjectId(eq(id), any(), any())).thenReturn(mockReadableObjectId);
        when(mockReadableObjectId.resolve()).thenReturn(expectedPojo);

        // Act
        Object result = deserializer.exposeDeserializeFromObjectId(mockParser, mockContext);

        // Assert
        assertEquals(expectedPojo, result);
        verify(mockObjectIdReader).readObjectReference(mockParser, mockContext);
        verify(mockContext).findObjectId(eq(id), any(), any());
        verify(mockReadableObjectId).resolve();
    }

    @Test(expected = UnresolvedForwardReference.class)
    public void testDeserializeFromObjectId_ThrowsUnresolvedForwardReference() throws IOException {
        // Arrange
        Object id = "id-456";
        JsonStreamContext mockLocation = mock(JsonStreamContext.class);

        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(id);
        when(mockContext.findObjectId(eq(id), any(), any())).thenReturn(mockReadableObjectId);
        // Simulate that the object is not yet resolved (e.g., forward reference)
        when(mockReadableObjectId.resolve()).thenReturn(null);
        when(mockParser.getCurrentLocation()).thenReturn(mockLocation);

        // Act
        deserializer.exposeDeserializeFromObjectId(mockParser, mockContext);

        // Assert: Exception expected
    }

    /**
     * Helper to simulate the UnresolvedForwardReference if not accessible in the classpath, 
     * but since it's part of Jackson, it should be available.
     */
    private static class UnresolvedForwardReference extends JsonMappingException {
        public UnresolvedForwardReference(JsonParser p, String msg, JsonStreamContext loc, ReadableObjectId roid) {
            super(p, msg);
        }
    }
}
